<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<script>
document.addEventListener('DOMContentLoaded', function () { const form=document.querySelector('.finance-filter'); const dates=form?.querySelectorAll('input[type="date"]'); dates?.forEach(input=>input.addEventListener('change',()=>{ if(dates[0].value&&dates[1].value) form.requestSubmit(); })); const ctx=document.getElementById('financeChart'); if(!ctx||!window.Chart)return; new Chart(ctx,{type:'line',data:{labels:@json($chartData['labels']),datasets:[{label:'Customer payments',data:@json($chartData['gross']),borderColor:'#2563eb',backgroundColor:'rgba(37,99,235,.08)',fill:true,tension:.35},{label:'Completed-order seller earnings',data:@json($chartData['net']),borderColor:'#16a34a',tension:.35},{label:'Business expenses',data:@json($chartData['expenses']),borderColor:'#dc2626',tension:.35}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom'}},scales:{y:{ticks:{callback:v=>'₱'+Number(v).toLocaleString()}}}}}); setTimeout(()=>location.reload(),60000); });
</script>
<script>
document.addEventListener('DOMContentLoaded', function () {
  const modals = document.querySelectorAll('.finance-detail-modal');
  modals.forEach(modal => document.body.appendChild(modal));
  const close = modal => { modal.classList.remove('open'); modal.setAttribute('aria-hidden', 'true'); document.body.classList.remove('finance-modal-open'); const opener = modal._opener; if (opener) opener.focus(); };
  document.querySelectorAll('[data-finance-modal-open]').forEach(button => button.addEventListener('click', () => { const modal = document.getElementById(button.dataset.financeModalOpen); if (!modal) return; modal._opener = button; modal.classList.add('open'); modal.setAttribute('aria-hidden', 'false'); document.body.classList.add('finance-modal-open'); modal.querySelector('[data-finance-modal-close]').focus(); }));
  modals.forEach(modal => { modal.addEventListener('click', event => { if (event.target === modal) close(modal); }); modal.querySelectorAll('[data-finance-modal-close]').forEach(button => button.addEventListener('click', () => close(modal))); });
  document.addEventListener('keydown', event => { if (event.key === 'Escape') modals.forEach(modal => { if (modal.classList.contains('open')) close(modal); }); });
});
</script>
